#include <cstddef>
#include <cstdint>
static void put_i32(std::uint8_t*out,std::size_t off,std::int64_t x){auto b=static_cast<std::uint32_t>(static_cast<std::int32_t>(x));for(std::size_t k=0;k<4;k++)out[off+k]=static_cast<std::uint8_t>(b>>(8*k));}
extern "C" std::int64_t operators(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<5)return -1;auto op=v[0],ra=v[1],ca=v[2];if((op!=0&&op!=1)||ra<1||ra>16||ca<0||ca>16||ra*ca>256)return -1;auto count=static_cast<std::size_t>(ra*ca),pb=3+count;if(n<pb+2)return -1;auto rb=v[pb],cb=v[pb+1];if(rb<1||rb>16||cb<0||cb>16||rb*cb>256||n!=pb+2+static_cast<std::size_t>(rb*cb))return -1;for(std::size_t i=0;i<count;i++)if(v[3+i]<-1000000||v[3+i]>1000000)return -1;for(std::size_t i=0;i<static_cast<std::size_t>(rb*cb);i++)if(v[pb+2+i]<-1000000||v[pb+2+i]>1000000)return -1;if(ra!=rb||ca!=cb)return -1;auto bytes=count*4;if(cap<bytes||(bytes&&!out))return -2;for(std::size_t i=0;i<count;i++){auto a=v[3+i],b=v[pb+2+i];put_i32(out,i*4,op==0?a+b:a-b);}return static_cast<std::int64_t>(count);}
